const search = (variables['f4c81e5e-2cb0-4cb8-97b1-6e0faa31f5a1'] || '').toLowerCase();
const filter = variables['1170b393-0d80-429f-ae05-de27e4d946ff'] || 'All';

function getTopicStats(topic) {
  const topicId = topic?.id;
  const topicQuestionIds = [];
  for (let i = 0; i < questions.length; i++) {
    if (String(questions[i]?.topic_id) === String(topicId)) {
      topicQuestionIds.push(questions[i].id);
    }
  }
  const questionCount = Math.max(Number(topic?.question_count) || 0, topicQuestionIds.length);
  let attempted = 0;
  let correct = 0;
  for (let j = 0; j < attempts.length; j++) {
    if (topicQuestionIds.indexOf(attempts[j]?.question_id) >= 0) {
      attempted++;
      if (attempts[j]?.is_correct) correct++;
    }
  }
  const mastery = attempted ? Math.round((correct / attempted) * 100) : 0;
  let statusLabel = 'Not started';
  if (attempted > 0) {
    if (mastery >= 80) statusLabel = 'Strong';
    else if (mastery >= 40) statusLabel = 'Improving';
    else statusLabel = 'Weak';
  }
  return {
    questionCount: questionCount,
    questionsAttempted: attempted,
    mastery: mastery,
    statusLabel: statusLabel
  };
}

const enriched = topics.map(function(topic) {
  const stats = getTopicStats(topic);
  return {
    id: topic?.id,
    name: topic?.name,
    description: topic?.description,
    code: topic?.code,
    category: topic?.category,
    question_count: stats.questionCount,
    questionCount: stats.questionCount,
    questionsAttempted: stats.questionsAttempted,
    mastery: stats.mastery,
    statusLabel: stats.statusLabel
  };
});

return enriched.filter(function(topic) {
  const name = (topic?.name || '').toLowerCase();
  const desc = (topic?.description || '').toLowerCase();
  const matchesSearch = !search || name.includes(search) || desc.includes(search);
  const matchesFilter = filter === 'All' || topic?.statusLabel === filter;
  return matchesSearch && matchesFilter;
});

